impl PathOp {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        match self {
            Self::MoveTo(v) => {
                out.push_str("MoveTo(");
                v.dump(out, t);
                out.push(')');
            }
            Self::LineTo(v) => {
                out.push_str("LineTo(");
                v.dump(out, t);
                out.push(')');
            }
            Self::BezierTo(v) => {
                out.push_str("BezierTo(");
                v.dump(out, t);
                out.push(')');
            }
            Self::QuadTo(v) => {
                out.push_str("QuadTo(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Arc(v) => {
                out.push_str("Arc(");
                v.dump(out, t);
                out.push(')');
            }
            Self::ArcTo(v) => {
                out.push_str("ArcTo(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Ellipse(v) => {
                out.push_str("Ellipse(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Rect(v) => {
                out.push_str("Rect(");
                v.dump(out, t);
                out.push(')');
            }
            Self::Close => out.push_str("Close"),
            Self::RoundRect(v) => {
                out.push_str("RoundRect(");
                v.dump(out, t);
                out.push(')');
            }
        }
    }

    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(10) {
            0 => Self::MoveTo(Pair::random(rng, b, depth + 1)),
            1 => Self::LineTo(Pair::random(rng, b, depth + 1)),
            2 => Self::BezierTo(Cubic::random(rng, b, depth + 1)),
            3 => Self::QuadTo(Quad::random(rng, b, depth + 1)),
            4 => Self::Arc(ArcOp::random(rng, b, depth + 1)),
            5 => Self::ArcTo(ArcToOp::random(rng, b, depth + 1)),
            6 => Self::Ellipse(EllipseOp::random(rng, b, depth + 1)),
            7 => Self::Rect(Rect4::random(rng, b, depth + 1)),
            8 => Self::Close,
            _ => Self::RoundRect(RoundRectOp::random(rng, b, depth + 1)),
        }
    }
}

