    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        match rng.below(52) {
            0 => Self::Save,
            1 => Self::Restore,
            2 => Self::Translate(Pair::random(rng, b, depth + 1)),
            3 => Self::Rotate(rng.f64_edge()),
            4 => Self::Scale(Pair::random(rng, b, depth + 1)),
            5 => Self::Transform(Mat6::random(rng, b, depth + 1)),
            6 => Self::SetTransform(Mat6::random(rng, b, depth + 1)),
            7 => Self::ResetTransform,
            8 => Self::CaptureCtm(rng.u32_edge()),
            9 => Self::TransformByInverseOf(rng.u32_edge()),
            10 => Self::TransformUnshape(rng.u32_edge()),
            11 => Self::SetTransformReg(rng.u32_edge()),
            12 => Self::GlobalAlpha(rng.f64_edge()),
            13 => Self::GlobalAlphaMul(rng.f64_edge()),
            14 => Self::Composite(CompositeOp::random(rng, b, depth + 1)),
            15 => Self::FilterSet(rng.below(b.sym)),
            16 => Self::FilterNone,
            17 => Self::FillStyle(Paint::random(rng, b, depth + 1)),
            18 => Self::StrokeStyle(Paint::random(rng, b, depth + 1)),
            19 => Self::LineWidth(rng.f64_edge()),
            20 => Self::LineJoin(Join::random(rng, b, depth + 1)),
            21 => Self::LineCap(Cap::random(rng, b, depth + 1)),
            22 => Self::MiterLimit(rng.f64_edge()),
            23 => Self::LineDash(Span::random(rng, b, depth + 1)),
            24 => Self::ShadowColor(rng.below(b.sym)),
            25 => Self::ShadowBlur(rng.f64_edge()),
            26 => Self::ShadowOffset(ShadowOff::random(rng, b, depth + 1)),
            27 => Self::Font(FontRef::random(rng, b, depth + 1)),
            28 => Self::ChartFont(FontRef::random(rng, b, depth + 1)),
            29 => Self::FillText(FillTextItem::random(rng, b, depth + 1)),
            30 => Self::TextAlign(Align::random(rng, b, depth + 1)),
            31 => Self::TextBaseline(Baseline::random(rng, b, depth + 1)),
            32 => Self::ImageSmoothing(rng.bool()),
            33 => Self::BeginPath,
            34 => Self::AppendPath(Span::random(rng, b, depth + 1)),
            35 => Self::Fill(FillRule::random(rng, b, depth + 1)),
            36 => Self::Stroke,
            37 => Self::Clip(FillRule::random(rng, b, depth + 1)),
            38 => Self::FillRect(Rect4::random(rng, b, depth + 1)),
            39 => Self::StrokeRect(Rect4::random(rng, b, depth + 1)),
            40 => Self::ClearRect(Rect4::random(rng, b, depth + 1)),
            41 => Self::DrawImage(DrawImageItem::random(rng, b, depth + 1)),
            42 => Self::Prepare(ImageSrc::random(rng, b, depth + 1)),
            43 => Self::Text(rng.u32_edge()),
            44 => Self::LayerBegin(LayerBeginItem::random(rng, b, depth + 1)),
            45 => Self::LayerEnd(LayerEndItem::random(rng, b, depth + 1)),
            46 => Self::DrawLayer(rng.u32_edge()),
            47 => Self::ReleaseLayer(rng.u32_edge()),
            48 => Self::Effect(rng.u32_edge()),
            49 => Self::SlotBegin(rng.u32_edge()),
            50 => Self::SlotEnd,
            _ => Self::MediaFrame(MediaFrameItem::random(rng, b, depth + 1)),
        }
    }
