impl WarpPaint {
    pub fn dump(&self, out: &mut String, t: &Tables) {
        out.push('{');
        out.push_str("kind:");
        self.kind.dump(out, t);
        out.push_str(",angle:");
        match self.angle {
            Some(v) => {
                uo_codec::dump::f64(out, v);
            }
            None => out.push('-'),
        }
        out.push_str(",scaled:");
        out.push_str(if self.scaled { "true" } else { "false" });
        out.push_str(",stops:");
        out.push('[');
        for (i0, e0) in self.stops.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",path:");
        match self.path {
            Some(v) => {
                uo_codec::dump::utf16(out, t.sym_units(v));
            }
            None => out.push('-'),
        }
        out.push_str(",fill_to:");
        match &self.fill_to {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push_str(",raw:");
        out.push('[');
        for (i0, e0) in self.raw.iter().enumerate() {
            if i0 > 0 { out.push(','); }
            e0.dump(out, t);
        }
        out.push(']');
        out.push_str(",image:");
        match &self.image {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push_str(",tile:");
        match &self.tile {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push_str(",fill_rect:");
        match &self.fill_rect {
            Some(v) => {
                v.dump(out, t);
            }
            None => out.push('-'),
        }
        out.push('}');
    }
}

impl WarpPaint {
    pub fn random(rng: &mut Rng, b: &Bounds, depth: u32) -> Self {
        Self {
            kind: WarpPaintKind::random(rng, b, depth + 1),
            angle: if rng.bool() { Some(rng.f64_edge()) } else { None },
            scaled: rng.bool(),
            stops: { let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| Stop::random(rng, b, depth + 1)).collect::<Vec<_>>() },
            path: if rng.bool() { Some(rng.below(b.sym)) } else { None },
            fill_to: if rng.bool() { Some(Edges::random(rng, b, depth + 1)) } else { None },
            raw: { let n = if depth > 3 { 0 } else if depth == 0 && rng.below(48) == 0 { 130 + rng.below(100) } else { rng.below(4) }; (0..n).map(|_| RawStop::random(rng, b, depth + 1)).collect::<Vec<_>>() },
            image: if rng.bool() { Some(ImageSrc::random(rng, b, depth + 1)) } else { None },
            tile: if rng.bool() { Some(TileParams::random(rng, b, depth + 1)) } else { None },
            fill_rect: if rng.bool() { Some(Edges::random(rng, b, depth + 1)) } else { None },
        }
    }
}

