/// Dumps every table entry (the entries a stream of messages carried).
pub fn dump_tables(tables: &Tables) -> String {
    let t = tables;
    let mut out = String::new();
    out.push_str("sym=[");
    for (i, e) in t.sym.iter().enumerate() {
        if i > 0 { out.push(','); }
        uo_codec::dump::utf16(&mut out, e);
    }
    out.push_str("];");
    out.push_str("faces=[");
    for (i, e) in t.faces.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("media=[");
    for (i, e) in t.media.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("derived=[");
    for (i, e) in t.derived.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out.push_str("bitmaps=[");
    for (i, e) in t.bitmaps.iter().enumerate() {
        if i > 0 { out.push(','); }
        e.dump(&mut out, t);
    }
    out.push_str("];");
    out
}

/// The new entries of one message (`first`: at least one per table, so ids can refer to something), and the bounds the body may use.
pub fn random_delta(rng: &mut Rng, tables: &Tables, generation: u32, first: bool) -> (Delta, Bounds) {
    let mut d = Delta { generation, ..Delta::default() };
    let mut b = Bounds::default();
    let from_sym = u32::try_from(tables.sym.len()).unwrap_or(0);
    let count_sym = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.sym.from = from_sym;
    b.sym = from_sym + count_sym;
    let from_faces = u32::try_from(tables.faces.len()).unwrap_or(0);
    let count_faces = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.faces.from = from_faces;
    b.faces = from_faces + count_faces;
    let from_media = u32::try_from(tables.media.len()).unwrap_or(0);
    let count_media = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.media.from = from_media;
    b.media = from_media + count_media;
    let from_derived = u32::try_from(tables.derived.len()).unwrap_or(0);
    let count_derived = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.derived.from = from_derived;
    b.derived = from_derived + count_derived;
    let from_bitmaps = u32::try_from(tables.bitmaps.len()).unwrap_or(0);
    let count_bitmaps = if first { 1 + rng.below(3) } else { rng.below(3) };
    d.bitmaps.from = from_bitmaps;
    b.bitmaps = from_bitmaps + count_bitmaps;
    for i in 0..count_sym { d.sym.items.push(rng.unique_utf16(from_sym + i, 4)); }
    for _ in 0..count_faces { d.faces.items.push(FaceKey::random(rng, &b, 1)); }
    for _ in 0..count_media { d.media.items.push(Media::random(rng, &b, 1)); }
    for _ in 0..count_derived { d.derived.items.push(Derived::random(rng, &b, 1)); }
    for _ in 0..count_bitmaps { d.bitmaps.items.push(Bitmap::random(rng, &b, 1)); }
    (d, b)
}

/// Appends the entries of `delta` to `tables` (what the decoder does), so a following delta starts after them.
pub fn apply_delta(tables: &mut Tables, delta: &Delta) {
    if tables.generation != Some(delta.generation) { tables.clear(); tables.generation = Some(delta.generation); }
    tables.sym.extend(delta.sym.items.iter().cloned());
    tables.faces.extend(delta.faces.items.iter().cloned());
    tables.media.extend(delta.media.items.iter().cloned());
    tables.derived.extend(delta.derived.items.iter().cloned());
    tables.bitmaps.extend(delta.bitmaps.items.iter().cloned());
}

